<?php
require_once __DIR__.'/includes/bootstrap.php';
if (empty($_SESSION['user_id'])) go('/spi/');
page_start('Dashboard'); echo '<h1>Dashboard</h1>';
if ($_SESSION['role']==='admin') { $students=(int)$conn->query("SELECT COUNT(*) FROM students WHERE record_status='active'")->fetch_row()[0]; $pending=(int)$conn->query("SELECT COUNT(*) FROM student_account_requests WHERE request_status='pending'")->fetch_row()[0]; $teachers=(int)$conn->query("SELECT COUNT(*) FROM users WHERE role='teacher' AND account_status='active'")->fetch_row()[0]; echo '<div class="grid"><div class="card stat"><b>'.$students.'</b>Active student records</div><div class="card stat"><b>'.$pending.'</b>Requests awaiting review</div><div class="card stat"><b>'.$teachers.'</b>Active teachers</div></div><p>Use the navigation to manage student accounts and records, academic setup, teachers, and class assignments.</p>'; }
elseif ($_SESSION['role']==='teacher') echo '<div class="card"><h2>Teacher workspace</h2><p>Open My classes to review assigned subjects and enter grades.</p></div>';
else { $st=$conn->prepare('SELECT request_status,rejection_reason FROM student_account_requests WHERE user_id=? ORDER BY request_id DESC LIMIT 1');$st->bind_param('i',$_SESSION['user_id']);$st->execute();$r=$st->get_result()->fetch_assoc(); if(($r['request_status']??'')==='approved') echo '<div class="card"><h2>Welcome, '.e($_SESSION['name']).'</h2><p>Your account is verified. Released grades are available in My grades.</p></div>'; else echo '<div class="card"><h2>Your account is active</h2><p>You can sign in and use your account. Grade access is pending identity verification against official school records.</p>'.(!empty($r['rejection_reason'])?'<p>Verification note: '.e($r['rejection_reason']).'</p>':'').'</div>'; }
page_end();
